enum EquipmentState{running,standby,maintenance,outOfService,taggedOut}
enum Priority{normal,important,critical}
enum ActionState{open,inProgress,waiting,completed}
class Equipment{final String tag,name,area;EquipmentState state;String note;Equipment({required this.tag,required this.name,required this.area,this.state=EquipmentState.running,this.note=''});Map<String,dynamic> toJson()=>{'tag':tag,'name':name,'area':area,'state':state.name,'note':note};factory Equipment.fromJson(Map<String,dynamic> j)=>Equipment(tag:j['tag']??'',name:j['name']??'',area:j['area']??'',state:EquipmentState.values.firstWhere((e)=>e.name==j['state'],orElse:()=>EquipmentState.running),note:j['note']??'');}
class LogEntry{final String id,text;final DateTime createdAt;final String? equipmentTag;final Priority priority;final String source;LogEntry({required this.id,required this.createdAt,required this.text,this.equipmentTag,this.priority=Priority.normal,this.source='manual'});Map<String,dynamic> toJson()=>{'id':id,'createdAt':createdAt.toIso8601String(),'text':text,'equipmentTag':equipmentTag,'priority':priority.name,'source':source};factory LogEntry.fromJson(Map<String,dynamic> j)=>LogEntry(id:j['id']??'',createdAt:DateTime.tryParse(j['createdAt']??'')??DateTime.now(),text:j['text']??'',equipmentTag:j['equipmentTag'],priority:Priority.values.firstWhere((e)=>e.name==j['priority'],orElse:()=>Priority.normal),source:j['source']??'manual');}
class WatchItem{final String id,title,detail;final String? equipmentTag;bool active;WatchItem({required this.id,required this.title,required this.detail,this.equipmentTag,this.active=true});Map<String,dynamic> toJson()=>{'id':id,'title':title,'detail':detail,'equipmentTag':equipmentTag,'active':active};factory WatchItem.fromJson(Map<String,dynamic> j)=>WatchItem(id:j['id']??'',title:j['title']??'',detail:j['detail']??'',equipmentTag:j['equipmentTag'],active:j['active']??true);}
class OperatorTask{final String id,title;final String? equipmentTag;DateTime? dueAt;ActionState state;OperatorTask({required this.id,required this.title,this.equipmentTag,this.dueAt,this.state=ActionState.open});Map<String,dynamic> toJson()=>{'id':id,'title':title,'equipmentTag':equipmentTag,'dueAt':dueAt?.toIso8601String(),'state':state.name};factory OperatorTask.fromJson(Map<String,dynamic> j)=>OperatorTask(id:j['id']??'',title:j['title']??'',equipmentTag:j['equipmentTag'],dueAt:j['dueAt']==null?null:DateTime.tryParse(j['dueAt']),state:ActionState.values.firstWhere((e)=>e.name==j['state'],orElse:()=>ActionState.open));}
class ProcedureItem{final String title,category,source;const ProcedureItem(this.title,this.category,this.source);}
